+                sw = *arg++;
+                     SWBOOLEAN('q',quiet)
+		else SWBOOLEAN('c',cswitch)
+		else SWBOOLEAN('L',Lswitch)
+		else SWRANGE('n',":-",nswitch,nmin,nmax,"assembleg -n")
+		else SWRANGE('i',":-",iswitch,imin,imax,"assembleg -i")
+                else badargs = TRUE;
+            }
+        }
+        else
+        {
+            ++argnum;
+            if      (argnum == 1) infilename = arg;
