+/********************************************************************/
+
+static int
+hasinout(cubgraph cub,
+         int n, int ne, int *x0, int *x1, int *y0, int *y1, int limit)
+/* test if cub has in-out (+-) property */
+{
+	edgevec v1,v2,initclass,outclass;
+	set *d0,*di,*dii;
+	int i,ii,j,jj;
+	int me,nbad;
+        DYNALLSTAT(graph,done,done_sz);
+	
+	me = (ne + WORDSIZE - 1) / WORDSIZE;
+
+        DYNALLOC2(graph,done,done_sz,ne,me,"hasinout");
+
+	d0 = (set*)done;
+	EMPTYSET(d0,me);
+	for (j = 0; j < ne; ++j)
+	    ADDELEMENT(d0,j);
+
+	for (i = 1, di = d0 + me; i < ne; ++i, di += me)
+	{
+	    for (j = 0; j < me; ++j)
+		di[j] = d0[j];
+	    DELELEMENT(di,i);
+	}
+	DELELEMENT(d0,0);
+
+	cubinit(cub,eno,v1,v2,n,ne);
+	for (i = 0; i < ne; ++i)
+	    initclass[i] = DUNNO;
+
+	maxnodes = NO_LIMIT;
+	nbad = 0;
+
+	for (i = 0, di = (set*)done; i < ne; ++i, di += me)
+	    for (j = -1; (j = nextelement(di,me,j)) >= 0;)
+	    {
+		initclass[i] = NO;
+		initclass[j] = YES;
+		++numtries[0];
+		if (cubham(cub,eno,initclass,v1,v2,NULL,
+							outclass,n,ne) == NO)
+		{
+		    x0[nbad] = v1[i]; x1[nbad] = v2[i];
+		    y0[nbad] = v1[j]; y1[nbad] = v2[j];
+		    ++nbad;
+		    if (nbad >= limit) return nbad;
+		}
+		else
+		{
+                    for (ii = i, dii = di; ii < ne; ++ii, dii += me)
+                    if (outclass[ii] == NO)
+                        for (jj = 0; jj < ne; ++jj)
+                            if (outclass[jj] == YES)
+                                DELELEMENT(dii,jj);
+		}
+
+		initclass[i] = DUNNO;
+		initclass[j] = DUNNO;
+	    }
+
+	return nbad;
+}
+
+/**************************************************************************/
+
+static int
+hasinin(cubgraph cub,
+        int n, int ne, int *x0, int *x1, int *y0, int *y1, int limit)
+/* test if cub has in-in (++) property */
+{
+        edgevec v1,v2,initclass,outclass;
+	set *d0,*di,*dii;
+	int i,ii,j,jj;
+	int me,nbad;
+        DYNALLSTAT(graph,done,done_sz);
+	
+	me = (ne + WORDSIZE - 1) / WORDSIZE;
+
+        DYNALLOC2(graph,done,done_sz,ne,me,"hasinin");
+
+	d0 = (set*)done;
+	EMPTYSET(d0,me);
+	for (j = 0; j < ne; ++j)
+	    ADDELEMENT(d0,j);
+
+	for (i = 1, di = d0 + me; i < ne; ++i, di += me)
+	{
+	    for (j = 0; j < me; ++j)
+		di[j] = d0[j];
+	    DELELEMENT(di,i);
+	}
+	DELELEMENT(d0,0);
+
+	cubinit(cub,eno,v1,v2,n,ne);
+	for (i = 0; i < ne; ++i)
+	    initclass[i] = DUNNO;
+
+	maxnodes = NO_LIMIT;
+	nbad = 0;
+
+	for (i = 0, di = (set*)done; i < ne; ++i, di += me)
+	    for (j = i; (j = nextelement(di,me,j)) >= 0;)
+	    {
+		initclass[i] = YES;
+		initclass[j] = YES;
+		++numtries[0];
+		if (cubham(cub,eno,initclass,v1,v2,NULL,outclass,n,ne) == NO)
+		{
+                    x0[nbad] = v1[i]; x1[nbad] = v2[i];
+                    y0[nbad] = v1[j]; y1[nbad] = v2[j];
+                    ++nbad;
+                    if (nbad >= limit) return nbad;
+		}
+		else
+	 	{
+                    for (ii = i, dii = di; ii < ne; ++ii, dii += me)
+                    if (outclass[ii] == YES)
+                        for (jj = ii; jj < ne; ++jj)
+                            if (outclass[jj] == YES)
+                                DELELEMENT(dii,jj);
+		}
+
+		initclass[i] = DUNNO;
+		initclass[j] = DUNNO;
+	    }
+	return nbad;
+}
