+/**************************************************************************/
+
+static int
+hasout(cubgraph cub, int n, int ne, int weight, int *x0, int *x1, int limit)
+/* test if cub has "out" property 
+   Returns are -2 for timeout, -1 for nonhamiltonian, otherwise
+   number of edges not present in any cycle */
+{
+	cubgraph done;
+	int cyc[MAXN];
+        int vv[2],vi[2];
+        int nbad,ch;
