+                    ADDELEMENT(gw,v);
+                }
+            }
+        }
+        FREES(g);
+    }
+    t = CPUTIME - t;
+
+    if (!quiet)
+        fprintf(stderr,
+          ">Z  " COUNTER_FMT " graphs read from %s, "
+                      COUNTER_FMT " written to %s; %3.2f sec.\n",
+                nin,infilename,nout,outfilename,t);
+
+    exit(0);
+}

