+#endif
+
+#ifdef DREADTEST
+    seed = 1;
+    ran_init(seed);
+#else
+#ifdef  INITSEED
+    INITSEED;
+    ran_init(seed);
+#endif
+#endif
+
+    umask = 0;
+    pvalid = FALSE;
+    ovalid = FALSE;
+    gvalid = gvalid_sg = FALSE;  /* at most one valid */
+    cvalid = cvalid_sg = FALSE;  /* at most one valid */
