+            minus = FALSE;
+	    break;
+
+	case 'd': 
+	    options_digraph = !minus;
+            minus = FALSE;
+	    break;
+
+	case 'P': 
+	    options_keepgroup = !minus;
+            minus = FALSE;
+	    break;
+
+	case 'w':
+	    while (*ap == '=' || *ap == ' ') ++ap;
+            arg_int(&ap,&worksize,"w");
+#if MAXN
