+            minus = FALSE;
+            break;
+
+	case 'V':
+	    if (minus)
+            {
+                options_verbosity = 0;
+                minus = FALSE;
+            }
+            else
+            {
+	        while (*ap == '=' || *ap == ' ') ++ap;
