+            }
+            break;
+
+
+	case 'S':
+	    if (minus)
+            {
+                options_strategy = 0;
+                minus = FALSE;
+            }
+            else
+            {
+	        while (*ap == '=' || *ap == ' ') ++ap;
+                arg_int(&ap,&i,"S");
+/*
+                if (i < 0) fprintf(ERRFILE,"strategy must be >= 0\n");
+                else       options_strategy = i;
+*/
+		if (i != 0) fprintf(ERRFILE,
+                      "Only strategy 0 is supported in this version\n");
+            }
+            break;
+
+        case 'G': 
+            if (minus)
+            {
+                options_schreier = 0;
+                minus = FALSE;
+            }
+            else
+            {
+	        while (*ap == '=' || *ap == ' ') ++ap;
