+                {
+                    options_schreier = i;
+                    if (i > 0) schreier_fails(i);
+                }
+            }
+            break;
+
+        case 'y': 
+	    while (*ap == '=' || *ap == ' ') ++ap;
+            arg_int(&ap,&options_tc_level,"y");
+            minus = FALSE;
+            break;
+
+        case '$': 
+	    while (*ap == '=' || *ap == ' ') ++ap;
+            arg_int(&ap,&labelorg,"$");
+            minus = FALSE;
+            break;
+
+        case 'M': 
+	    if (minus)
+	    {
+	        multiplicity = 1;
+		mintime = 0.0;
+                minus = FALSE;
+	    }
+	    else
+	    {
+		actmult = 0;
+	        while (*ap == '=' || *ap == ' ') ++ap;
+                arg_int(&ap,&multiplicity,"M");
+		if (*ap == '/')
+		{
+		    ++ap;
+		    arg_int(&ap,&actmult,"M/");
+		}
+	        if (multiplicity < 0) multiplicity = 0;
+	        if (actmult < 0) actmult = 0;
+		if (multiplicity == 0 && actmult == 0) multiplicity = 1;
+		mintime = (double)actmult;
+            }
+            break;
+
+        case 'l': 
+	    while (*ap == '=' || *ap == ' ') ++ap;
+            arg_int(&ap,&options_linelength,"l");
+            minus = FALSE;
+            break;
+
+        case 'A': 
+	    d = *ap++;
+            if (d == 'n' || d == 'N' || d == 'd' || d == 'D')
+		mode = DENSE_MODE;
+            else if (d == 's' || d == 'S') mode = SPARSE_MODE;
