+static void
+fragments(int *x, int nx, int *frag, int *nfrag)
+/* For each v in union(x[0..nx-1]), find the components of the
+   hypergraph x - v and add them to frag if there are more than one. */
+/* This implementation is shocking.  Improve it! */
+{
+    int allx,i,j,v;
+    int vbit,nw,w[MAXN];
+    boolean done;
+
+    allx = 0;
+    for (i = 0; i < nx; ++i) allx |= x[i];
+
+    *nfrag = 0;
+    
+    while (allx)
+    {
+        v = XNEXTBIT(allx);
+        vbit = xbit[v];
+        allx &= ~vbit;
+
+        for (i = 0; i < nx; ++i) w[i] = x[i] & ~vbit;
+        nw = nx;
+
+        done = FALSE;
+        while (!done && nw > 1)
+        {
+            done = TRUE;
+            for (i = 0; i < nw-1; ++i)
+            for (j = i+1; j < nw; )
+                if ((w[i] & w[j]) != 0)
+                {
+                    w[i] |= w[j];
+                    w[j] = w[nw-1];
+                    --nw;
+                    done = FALSE;
+                }
+                else
+                    ++j;
+        }
+    
+        if (nw > 1)
+            for (i = 0; i < nw; ++i)
+                frag[(*nfrag)++] = w[i];
+    }
+}
