+/**************************************************************************/
+
+static boolean
+accept2(graph *g, int n2, int x, graph *gx, int *deg, boolean nuniq)
+/* decide if n in theta(g+x) -- version for n+1 == maxn */
+{
+    int i,n;
+    int lab[MAXN],ptn[MAXN],orbits[MAXN];
+    int degx[MAXN],invar[MAXN];
+    setword vmax,gv;
+    int qn,qv;
+    int count[MAXN];
+    int xw;
+    int nx,numcells,code;
+    int degn,i0,i1,j,j0,j1;
+    set active[MAXM];
+    statsblk stats;
+    static DEFAULTOPTIONS_GRAPH(options);
+    setword workspace[50];
+
+#ifdef INSTRUMENT
+    ++a2calls;
+    if (nuniq) ++a2uniq;
+#endif
+    n = n1 + n2;
+    nx = n + 1;
+    for (i = 0; i < n; ++i)
+    {
+        gx[i] = g[i];
+        degx[i] = deg[i];
+    }
+    gx[n] = 0;
+    degx[n] = degn = XPOPCOUNT(x);
+
+    xw = x;
+    while (xw)
+    {
+        i = XNEXTBIT(xw);
+        xw &= ~xbit[i];
+        gx[i] |= bit[n];
+        gx[n] |= bit[i];
+        ++degx[i];
+    }
+#ifdef PRUNE1
+    if (PRUNE1(gx,degx,n1,n2+1,maxn2)) return FALSE;
+#endif
+
+    if (nuniq)
+    {
+#ifdef INSTRUMENT
+        ++a2succs;
+#endif
+#ifdef PRUNE2
+        if (PRUNE2(gx,degx,n1,n2+1,maxn2)) return FALSE;
+#endif
+        if (canonise) makecanon(gx,gcan,n1,n2+1);
+        return TRUE;
+    }
+
+    for (i = 0; i < n1; ++i)
+    {
+        lab[i] = i;
+        ptn[i] = 1;
+    }
+    ptn[n1-1] = 0;
+
+    i0 = n1;
+    i1 = n;
+    for (i = n1; i < nx; ++i)
+    {
+        if (degx[i] == degn) lab[i1--] = i;
+        else                 lab[i0++] = i;
+        ptn[i] = 1;
+    }
+
+    ptn[n] = 0;
+
+    if (i0 == n1)
+    {
+        numcells = 2;
+        active[0] = bit[0] | bit[n1];
+
+        if (!distinvar(gx,invar,n1,n2+1)) return FALSE;
+        qn = invar[n];
+        j0 = n1;
+        j1 = n;
+        while (j0 <= j1)
+        {
+            j = lab[j0];
+            qv = invar[j];
+            if (qv < qn)
+                ++j0;
+            else
+            {
+                lab[j0] = lab[j1];
+                lab[j1] = j;
+                --j1;
+            }
+        }
+        if (j0 > n1)
+        {
+            if (j0 == n)
+            {
+#ifdef INSTRUMENT
+                ++a2succs;
+#endif
+#ifdef PRUNE2
+                if (PRUNE2(gx,degx,n1,n2+1,maxn2)) return FALSE;
+#endif
+                if (canonise) makecanon(gx,gcan,n1,n2+1);
+                return TRUE;
+            }
+            ptn[j1] = 0;
+            ++numcells;
+            active[0] |= bit[j0];
+        }
+    }
+    else
+    {
+        numcells = 3;
+        ptn[i1] = 0;
+        active[0] = bit[0] | bit[n1] | bit[i1+1];
+
+        vmax = 0;
+        j = MAXN;
+        for (i = 0; i < n1; ++i)
+            if (degx[i] < j && degx[i] > 0)
+            {
+                j = degx[i];
+                vmax = bit[i];
+            }
+            else if (degx[i] == j)
+                vmax |= bit[i];
+
+        gv = gx[n] & vmax;
+        qn = POPCOUNT(gv);
+
+        j0 = i1+1;
+        j1 = n;
+        while (j0 <= j1)
+        {
+            j = lab[j0];
+            gv = gx[j] & vmax;
+            qv = POPCOUNT(gv);
+            if (qv > qn)
+                return FALSE;
+            else if (qv < qn)
+                ++j0;
+            else
+            {
+                lab[j0] = lab[j1];
+                lab[j1] = j;
+                --j1;
+            }
+        }
+        if (j0 > i1+1)
+        {
+            if (j0 == n)
+            {
+#ifdef INSTRUMENT
+                ++a2succs;
+#endif
+#ifdef PRUNE2
+                if (PRUNE2(gx,degx,n1,n2+1,maxn2)) return FALSE;
+#endif
+                if (canonise) makecanon(gx,gcan,n1,n2+1);
+                return TRUE;
+            }
+            ptn[j1] = 0;
+            ++numcells;
+            active[0] |= bit[j0];
+        }
+    }
+
+    refinex(gx,lab,ptn,0,&numcells,count,active,TRUE,&code,1,nx);
+
+    if (code < 0)
+        return FALSE;
+    else if (code > 0 || numcells >= nx-4)
+    {
+#ifdef INSTRUMENT
+        ++a2succs;
+#endif
+#ifdef PRUNE2
+        if (PRUNE2(gx,degx,n1,n2+1,maxn2)) return FALSE;
+#endif
+        if (canonise) makecanon(gx,gcan,n1,n2+1);
+        return TRUE;
+    }
+
+    options.writemarkers = FALSE;
+    options.writeautoms = FALSE;
+    options.getcanon = TRUE;
+    options.defaultptn = FALSE;
+
+    active[0] = 0;
+#ifdef INSTRUMENT
+    ++a2nauty;
+#endif
+    nauty(gx,lab,ptn,active,orbits,&options,&stats,workspace,50,1,nx,gcan);
+
+    if (orbits[lab[n]] == orbits[n])
+    {
+#ifdef INSTRUMENT
+        ++a2succs;
+#endif
+#ifdef PRUNE2
+    if (PRUNE2(gx,degx,n1,n2+1,maxn2)) return FALSE;
+#endif
+        if (canonise) makecanon(gx,gcan,n1,n2+1);
+        return TRUE;
+    }
+    else
+        return FALSE;
+}
+
+/**************************************************************************/
+
+static void
+xbnds(int n2, int ne, int dmax)
+/* find bounds on degree for vertex n2
+   Store answer in data[*].*  */
+{
+    int xlb,xub,m;
+
+    xlb = n2 == 0 ? (connec ? 1 : 0) : dmax;
+    if (xlb < mindeg2) xlb = mindeg2;
+    m = mine - ne - (maxn2 - n2 -1)*maxdeg2;
+    if (m > xlb) xlb = m;
+
+    xub = maxdeg2;
+    m = (maxe - ne) / (maxn2 - n2);
+    if (m < xub) xub = m;
+
+    data[n2].ne = ne;
+    data[n2].dmax = dmax;
+    data[n2].xlb = xlb;
+    data[n2].xub = xub;
+}
+
+/**************************************************************************/
+
+static void
+genextend(graph *g, int n2, int *deg, int ne, boolean rigid, int xlb, int xub)
+/* extend from n2 to n2+1 */
+{
+    int x,y,d;
+    int *xorb,xc;
+    int nx,i,j,imin,imax,dmax;
+    int xlbx,xubx,n;
+    graph gx[MAXN];
+    int degx[MAXN];
+    boolean rigidx;
+    int dneed,need,nfeet,hideg,deg1,ft[MAXN],nfrag,frag[MAXN];
+
+#ifdef INSTRUMENT
+    boolean haschild;
+
+    haschild = FALSE;
+    ++nodes[n2];
+    if (rigid) ++rigidnodes[n2];
+#endif
+
+    n = n1 + n2;
+    nx = n2 + 1;
+    dmax = deg[n-1];
+
+    d = 0;
+    dneed = mindeg1 - maxn2 + n2;
+    need = 0;
+    hideg = 0;
+    deg1 = 0;
+    for (i = 0; i < n1; ++i)
+    {
+        if (deg[i] == maxdeg1) d |= xbit[i];
+        if (deg[i] <= dneed) need |= xbit[i];
+        if (deg[i] >= 2) hideg |= xbit[i];
+        if (deg[i] == 1) deg1 |= xbit[i];
+    }
+
+    if (xlb < XPOPCOUNT(need)) xlb = XPOPCOUNT(need);
+    if (xlb > xub) return;
+
+    imin = xstart[xlb];
+    imax = xstart[xub+1];
+    xorb = data[n2].xorb;
+
+    if (nx == maxn2)
+    {
+        if (footfree)
+        {
+            nfeet = 0;
+            for (j = 0; j < n2; ++j)
+            {
+                x = xval[j] & hideg;
+                IFLE1BITS(x) ft[nfeet++] = xval[j] & deg1;
+            }
+        }
+        if (cutfree) fragments(xval,n2,frag,&nfrag);
+
+        for (i = imin; i < imax; ++i)
+        {
+            if (!rigid && xorb[i] != i) continue;
+            x = xset[i];
+            xc = xcard[i];
+            if ((x & d) != 0) continue;
+            if ((need & ~x) != 0) continue;
+
+            if (simple)
+            {
+                for (j = n2; --j >= 0;)
+                    if (x == xval[j]) break;
+                if (j >= 0) continue;
+            }
+            if (maxcommon >= 0)
+            {
+                for (j = n2; --j >= 0;)
+                {
+                    y = x & xval[j];
+                    if (XPOPCOUNT(y) > maxcommon) break;
+                }
+                if (j >= 0) continue;
+            }
+            if (mincommon >= 0)
+            {
+                for (j = n2; --j >= 0;)
+                {
+                    y = x & xval[j];
+                    if (XPOPCOUNT(y) < mincommon) break;
+                }
+                if (j >= 0) continue;
+            }
+	    if (antichain)
+	    {
+		for (j = 0; j < n2; ++j)
+		    if ((xval[j] & ~x) == 0) break;
+		if (j < n2) continue;
+	    }
+            if (footfree)
+            {
+                y = x & (hideg | deg1);
+                IFLE1BITS(y) continue;
+                for (j = 0; j < nfeet; ++j)
+                    if ((x & ft[j]) == 0) break;
+                if (j < nfeet) continue;
+            }
+            if (cutfree)
+            {
+                y = x & (hideg | deg1);
+                IFLE1BITS(y) continue;
+                for (j = 0; j < nfrag; ++j)
+                    if ((x & frag[j]) == 0) break;
+                if (j < nfrag) continue;
+            }
+
+            xval[n2] = x;
+
+            if (nx == nprune)
+            {
+                if (curres == 0) curres = mod;
+#ifdef SPLITTEST
+                --curres;
+                ++splitcases;
+                continue;
+#else
+                if (--curres != 0) continue;
+#endif
+            }
+            if (accept2(g,n2,x,gx,deg,xc > dmax))
+                if (!connec || isconnected(gx,n+1))
+                {
+                    ++ecount[ne+xc];
+#ifdef INSTRUMENT
+                    haschild = TRUE;
+#endif
+                    (*outproc)(outfile,canonise ? gcan : gx,n1,n2+1);
+                }
+        }
+    }
+    else
+    {
+        for (i = imin; i < imax; ++i)
+        {
+            if (!rigid && xorb[i] != i) continue;
+            x = xset[i];
+            xc = xcard[i];
+            if ((x & d) != 0) continue;
+            if ((need & ~x) != 0) continue;
+
+            if (nx == nprune)
+            {
+                if (curres == 0) curres = mod;
+#ifdef SPLITTEST
+                --curres;
+                ++splitcases;
+                continue;
+#else
+                if (--curres != 0) continue;
+#endif
+            }
+
+            if (simple)
+            {
+                for (j = n2; --j >= 0;)
+                    if (x == xval[j]) break;
+                if (j >= 0) continue;
+            }
+            if (maxcommon >= 0)
+            {
+                for (j = n2; --j >= 0;)
+                {
+                    y = x & xval[j];
+                    if (XPOPCOUNT(y) > maxcommon) break;
+                }
+                if (j >= 0) continue;
+            }
+            if (mincommon >= 0)
+            {
+                for (j = n2; --j >= 0;)
+                {
+                    y = x & xval[j];
+                    if (XPOPCOUNT(y) < mincommon) break;
+                }
+                if (j >= 0) continue;
+            }
+	    if (antichain)
+	    {
+		for (j = 0; j < n2; ++j)
+		    if ((xval[j] & ~x) == 0) break;
+		if (j < n2) continue;
+	    }
+            xval[n2] = x;
+
+            for (j = 0; j < n; ++j) degx[j] = deg[j];
+            if (data[nx].ne != ne+xc || data[nx].dmax != xc)
+                xbnds(nx,ne+xc,xc);
+            xlbx = data[nx].xlb;
+            xubx = data[nx].xub;
+            if (xlbx > xubx) continue;
+
+            data[nx].lo = xstart[xlbx];
+            data[nx].hi = xstart[xubx+1];
+            if (accept1(g,n2,x,gx,degx,&rigidx))
+            {
+#ifdef INSTRUMENT
+                haschild = TRUE;
+#endif
+                genextend(gx,nx,degx,ne+xc,rigidx,xlbx,xubx);
+            }
+        }
+    }
+#ifdef INSTRUMENT
+    if (haschild) ++fertilenodes[n2];
+#endif
+}
+
+/**************************************************************************/
+/**************************************************************************/
+
+int
+main(int argc, char *argv[])
+{
+    char *arg;
+    boolean badargs,gotD,gote,gotf,gotmr,gotY,gotZ,gotd,gotX;
+    long Dval1,Dval2;
+    long dval1,dval2;
+    int i,j,imin,imax,argnum,sw;
+    int splitlevinc;
+    graph g[MAXN1];
+    int deg[MAXN1];
+    nauty_counter nout;
+    double t1,t2;
+    char *outfilename;
+    char msg[201];
+
+    HELP; PUTVERSION;
+    nauty_check(WORDSIZE,1,MAXN,NAUTYVERSIONID);
+
+    if (MAXN > WORDSIZE || MAXN1 > 8*sizeof(int)-2)
+    {
+        fprintf(stderr,"genbg: incompatible MAXN, MAXN1 or WORDSIZE\n");
+        fprintf(stderr,"--See notes in program source\n");
+        exit(1);
+    }
+
+    badargs = FALSE;
+    connec = FALSE;
+    verbose = FALSE;
+    nautyformat = FALSE;
+    nooutput = FALSE;
+    canonise = FALSE;
+    greout = FALSE;
+    simple = FALSE;
+    graph6 = FALSE;
+    sparse6 = FALSE;
+    quiet = FALSE;
+    footfree = FALSE;
+    cutfree = FALSE;
+    antichain = FALSE;
+
+    gote = FALSE;
+    gotf = FALSE;
+    gotmr = FALSE;
+    gotD = FALSE;
+    gotd = FALSE;
+    gotY = gotZ = FALSE;
+    gotX = FALSE;
+    outfilename = NULL;
+
+    maxdeg1 = maxdeg2 = MAXN;
+    mindeg1 = mindeg2 = 0;
+
+    argnum = 0;
+    for (j = 1; !badargs && j < argc; ++j)
+    {
+        arg = argv[j];
+        if (arg[0] == '-' && arg[1] != '\0')
+        {
+            ++arg;
+            while (*arg != '\0')
+            {
+                sw = *arg++;
+                     SWBOOLEAN('n',nautyformat)
+                else SWBOOLEAN('u',nooutput)
+                else SWBOOLEAN('q',quiet)
+                else SWBOOLEAN('v',verbose)
+                else SWBOOLEAN('z',simple)
+                else SWBOOLEAN('F',footfree)
+                else SWBOOLEAN('L',cutfree)
+                else SWBOOLEAN('A',antichain)
+                else SWBOOLEAN('l',canonise)
+                else SWBOOLEAN('c',connec)
+                else SWBOOLEAN('a',greout)
+                else SWBOOLEAN('g',graph6)
+                else SWBOOLEAN('s',sparse6)
+                else SWINT('Y',gotY,mincommon,"genbg -Y")
+                else SWINT('Z',gotZ,maxcommon,"genbg -Z")
+                else SWINT('X',gotX,splitlevinc,"geng -X")
+                else SWRANGE('D',":-",gotD,Dval1,Dval2,"genbg -D")
+                else SWRANGE('d',":-",gotd,dval1,dval2,"genbg -d")
+#ifdef PLUGIN_SWITCHES
+PLUGIN_SWITCHES
+#endif
+                else badargs = TRUE;
+            }
+        }
+        else if (arg[0] == '-' && arg[1] == '\0')
+            gotf = TRUE;
+        else
+        {
+            if (argnum == 0)
+            {
+                if (sscanf(arg,"%d",&n1) != 1) badargs = TRUE;
+                ++argnum;
+            }
+            else if (argnum == 1)
+            {
+                if (sscanf(arg,"%d",&maxn2) != 1) badargs = TRUE;
+                ++argnum;
+            }
+            else if (gotf)
+                badargs = TRUE;
+            else
+            {
+                if (!gotmr)
+                {
+                    if (sscanf(arg,"%d/%d",&res,&mod) == 2)
+                    { 
+                        gotmr = TRUE; 
+                        continue; 
+                    }
+                }
+                if (!gote)
+                {
+                    if (sscanf(arg,"%d:%d",&mine,&maxe) == 2
+                     || sscanf(arg,"%d-%d",&mine,&maxe) == 2)
+                    {
+                        gote = TRUE;
+                        if (maxe == 0 && mine > 0) maxe = MAXN*MAXN/4;
+                        continue;
+                    }
+                    else if (sscanf(arg,"%d",&mine) == 1)
+                    {
+                        gote = TRUE;
+                        maxe = mine;
+                        continue;
+                    }
+                }
+                if (!gotf)
+                {
+                    outfilename = arg;
+                    gotf = TRUE;
+                    continue;
+                }
+            }
+        }
+    }
+
+    if (argnum < 2)
+        badargs = TRUE;
+    else if (n1 < 1 || maxn2 < 0 || n1 > MAXN1 || n1+maxn2 > MAXN)
+    {
+        fprintf(stderr,
+           ">E genbg: must have n1=1..%d, n1+n2=1..%d\n",MAXN1,MAXN);
+#if WORDSIZE==32
+	fprintf(stderr,"Try genbgL instead.\n");
+#endif
+        badargs = TRUE;
+    }
+
+    if (!gote)
+    {
+        mine = 0;
+        maxe = n1 * maxn2;
+    }
+
+    if (!gotmr)
+    {
+        mod = 1;
+        res = 0;
+    }
+    else if (argnum == 5 || argnum > 6)
+        badargs = TRUE;
+
+    if (gotd)
+    {
+        mindeg1 = dval1;
+        mindeg2 = dval2;
+    }
+    if (gotD)
+    {
+        maxdeg1 = Dval1;
+        maxdeg2 = Dval2;
+    }
+    if (maxdeg1 > maxn2) maxdeg1 = maxn2;
+    if (maxdeg2 > n1) maxdeg2 = n1;
+    if (connec && mine < n1+maxn2-1) mine = n1 + maxn2 - 1;
+    if (connec && mindeg1 == 0) mindeg1 = 1;
+    if (connec && mindeg2 == 0) mindeg2 = 1;
+    if (maxe > n1*maxdeg1) maxe =  n1*maxdeg1;
+    if (maxe > maxn2*maxdeg2) maxe =  maxn2*maxdeg2;
+    if (mine < n1*mindeg1) mine = n1*mindeg1;
+    if (mine < maxn2*mindeg2) mine = maxn2*mindeg2;
+
+    if (!gotZ) maxcommon = -1;
+    if (!gotY) mincommon = -1;
+
+    if (!badargs && (mine > maxe || maxe < 0 || maxdeg1 < 0 || maxdeg2 < 0))
+    {
+        fprintf(stderr,
+                ">E genbg: impossible mine,maxe,mindeg,maxdeg values\n");
+        badargs = TRUE;
+    }
+
+    if (badargs)
+    {
+        fprintf(stderr,">E Usage: %s\n",USAGE);
+        GETHELP;
+        exit(1);
+    }
+
+    if ((nautyformat!=0) + (graph6!=0) + (greout!=0)
+                         + (sparse6!=0) + (nooutput!=0) > 1)
+        gt_abort(">E genbg: -ungsa are incompatible\n");
+
+#ifdef OUTPROC
+    outproc = OUTPROC;
+#else
+#ifdef OUTPROC1
+    outproc = write12;
+#endif
+    if (nautyformat)   outproc = writenauty;
+    else if (nooutput) outproc = nullwrite;
+    else if (sparse6)  outproc = writes6x;
+    else if (greout)   outproc = writegre;
+    else               outproc = writeg6x;
+#endif
+
+#ifdef PLUGIN_INIT
+PLUGIN_INIT
+#endif
+
+    for (i = 0; i <= maxe; ++i) ecount[i] = 0;
+
+    if (nooutput)
+        outfile = stdout;
+    else if (!gotf || outfilename == NULL)
+    {
+        outfilename = "stdout";
+        outfile = stdout;
+    }
+    else if ((outfile = fopen(outfilename,
+                    nautyformat ? "wb" : "w")) == NULL)
+    {
+        fprintf(stderr,
+              ">E genbg: can't open %s for writing\n",outfilename);
+        gt_abort(NULL);
+    }
+
+    if (!quiet)
+    {
+        msg[0] = '\0';
+        if (strlen(argv[0]) > 75)
+            fprintf(stderr,">A %s",argv[0]);
+        else
+            CATMSG1(">A %s",argv[0]);
+        CATMSG4(" n=%d+%d e=%d:%d",n1,maxn2,mine,maxe);
+        CATMSG4(" d=%d:%d D=%d:%d ",mindeg1,mindeg2,maxdeg1,maxdeg2);
+        if (simple) CATMSG0("z");
+        if (footfree) CATMSG0("F");
+        if (antichain) CATMSG0("A");
+        if (connec) CATMSG0("c");
+        if (mincommon >= 0) CATMSG1("Y%d",mincommon);
+        if (maxcommon >= 0) CATMSG1("Z%d",maxcommon);
+        if (cutfree) CATMSG0("L");
+        if (canonise) CATMSG0("l");
+        if (mod > 1) CATMSG2(" class=%d/%d",res,mod);
+        CATMSG0("\n");
+        fputs(msg,stderr);
+        fflush(stderr);
+    }
+
+    class1size = n1;
+
+    for (i = 0; i < n1; ++i)
+    {
+        g[i] = 0;
+        deg[i] = 0;
+    }
+
+    t1 = CPUTIME;
+
+    if (maxn2 == 0)
+    {
+        if (res == 0)
+        {
+            ++ecount[0];
+            (*outproc)(outfile,g,n1,0);
+        }
+    }
+    else
+    {
+        makeleveldata();
+        curres = res;
+        if (mod <= 1)        nprune = 0;
+        else if (maxn2 >= 6) nprune = maxn2 - 2;
+        else if (maxn2 >= 3) nprune = maxn2 - 1;
+        else                 nprune = maxn2;
+
+        if (gotX)
+        {
+            nprune += splitlevinc;
+            if (nprune > maxn2) nprune = maxn2;
+            if (nprune < 0) nprune = 0;
+        }
+
+        xbnds(0,0,0);
+        imin = xstart[data[0].xlb];
+        imax = xstart[data[0].xub+1];
+
+        for (i = imin; i < imax; ++i)
+            data[0].xorb[i] = -1;
+
+        for (i = data[0].xlb; i <= data[0].xub; ++i)
+            data[0].xorb[xstart[i]] = xstart[i];
+
+        genextend(g,0,deg,0,FALSE,data[0].xlb,data[0].xub);
+    }
+    t2 = CPUTIME;
+
+    nout = 0;
+    for (i = 0; i <= maxe; ++i) nout += ecount[i];
+
+    if (verbose)
+        for (i = 0; i <= maxe; ++i)
+            if (ecount[i] != 0)
+            {
+                fprintf(stderr,">C " COUNTER_FMT " graphs with %d edges\n",
+                     ecount[i],i);
+            }
+
+#ifdef INSTRUMENT
+    fprintf(stderr,"\n>N node counts\n");
+    for (i = 0; i < maxn2; ++i)
+        fprintf(stderr," level %2d: %7ld (%ld rigid, %ld fertile)\n",
+                        i,nodes[i],rigidnodes[i],fertilenodes[i]);
+    fprintf(stderr,">A1 %ld calls to accept1, %ld nauty, %ld succeeded\n",
+                    a1calls,a1nauty,a1succs);
+    fprintf(stderr,
+         ">A2 %ld calls to accept2, %ld nuniq, %ld nauty, %ld succeeded\n",
+                    a2calls,a2uniq,a2nauty,a2succs);
+    fprintf(stderr,"\n");
+#endif
+
+#ifdef SPLITTEST
+    fprintf(stderr,">Z %lu splitting cases at level %d; cpu=%3.2f sec\n",
+            splitcases,nprune,t2-t1);
+#else
+#ifdef SUMMARY
+    SUMMARY(nout,t2-t1);
+#endif
+
+    if (!quiet)
+    {
+        fprintf(stderr,">Z " COUNTER_FMT " graphs generated in %3.2f sec\n",
+                nout,t2-t1);
+    }
+#endif
+
+    exit(0);
+}
